DO $source_v4$
DECLARE ctl jsonb;q record;h record;v record;rid bigint;newbounds jsonb;baseline jsonb;poststate jsonb;manifest jsonb;used bigint;available bigint;oldconstraint text;
BEGIN
ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
SELECT * INTO STRICT q FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id='resource:76d01ebd6a8015048f76895e0689f1f0b55574d393de488ec8f632aac3440047' FOR UPDATE;
IF q.scope_sha256 IS DISTINCT FROM ctl->>'scope_sha256' OR q.claim_token_sha256 IS DISTINCT FROM 'acf8197784ca8a31caa78a0fa42508774b9a867eae2261fc7b780ae1f9915674' OR q.status IS DISTINCT FROM 'CLAIMED' OR q.assignment_event_id<>35555 OR q.input_sha256 IS DISTINCT FROM '76d01ebd6a8015048f76895e0689f1f0b55574d393de488ec8f632aac3440047' OR q.claim_expires_at IS NULL OR q.claim_expires_at<=clock_timestamp() OR q.not_after<=clock_timestamp() OR q.owner_id IS DISTINCT FROM ctl->>'owner_id' OR q.owner_fence<>3 OR q.stop_generation<>1 OR q.assigned_executor IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' THEN RAISE EXCEPTION 'SOURCE_V4_CURRENT_EXACT_CLAIM_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=36878 AND event='ENGINEERING_CLEARING_CLAIMED_V6' AND details->>'clearing_id'=q.clearing_id AND details->>'executor'=q.assigned_executor) THEN RAISE EXCEPTION 'SOURCE_V4_EXACT_CLAIM_RECEIPT_REQUIRED';END IF;
SELECT * INTO STRICT v FROM population_top3000_202608_202609_v1.resource_probe_v3 WHERE probe_id='5deea88e-f95e-44d4-a816-276c35950969';
IF v.state IS DISTINCT FROM 'SUCCEEDED' OR v.owner_id IS DISTINCT FROM ctl->>'owner_id' OR v.owner_fence<>3 OR v.stop_generation<>1 OR v.scope_sha256 IS DISTINCT FROM ctl->>'scope_sha256' OR v.result_sha256 IS DISTINCT FROM '6ab48a5cb9549451b268ee9aef8d404135b32a313c66bc2d865a095be34e2915' OR v.result_sha256 IS DISTINCT FROM encode(sha256(convert_to(v.result::text,'UTF8')),'hex') OR (v.result->>'observed_at')::timestamptz<clock_timestamp()-interval '10 minutes' OR (v.result->>'observed_at')::timestamptz>clock_timestamp() THEN RAISE EXCEPTION 'SOURCE_V4_FRESH_EXACT_PROBE_REQUIRED';END IF;
IF current_setting('data_directory') NOT LIKE '/data/%' OR (SELECT count(*) FROM jsonb_array_elements(v.result->'metrics')m WHERE m->>'mountpoint'='/data')<>1 THEN RAISE EXCEPTION 'SOURCE_V4_DATA_MOUNT_REQUIRED';END IF;
SELECT (m->>'available_bytes')::bigint INTO available FROM jsonb_array_elements(v.result->'metrics')m WHERE m->>'mountpoint'='/data';
SELECT sum(pg_total_relation_size(c.oid)) INTO used FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND c.relkind IN('r','m');
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton AND a.max_source_bytes=1000000000 AND a.stored_bytes>=880000000 AND a.stored_bytes+a.reserved_bytes<1000000000 AND a.max_provider_requests=10000 AND a.max_http_invocations=10055 AND p.max_ticks=26000 AND p.deadline='2026-10-25T22:36:17.687194Z'::timestamptz AND p.budget_evidence#>>'{resource_limits,max_source_bytes}'='1000000000' AND p.budget_evidence#>>'{resource_limits,max_relation_bytes}'='12000000000' AND available-greatest(12000000000-used,0)-greatest(1500000000-a.stored_bytes-a.reserved_bytes,0)-a.reserved_bytes>=20000000000) THEN RAISE EXCEPTION 'SOURCE_V4_PREIMAGE_OR_PHYSICAL_HEADROOM_REJECTED';END IF;
SELECT pg_get_constraintdef(oid) INTO oldconstraint FROM pg_constraint WHERE conrelid='population_top3000_202608_202609_v1.acquisition_control'::regclass AND conname='acquisition_control_max_source_bytes_check';
IF oldconstraint IS DISTINCT FROM 'CHECK (((max_source_bytes >= 0) AND (max_source_bytes <= 1000000000)))' THEN RAISE EXCEPTION 'SOURCE_V4_CONSTRAINT_PREIMAGE_CHANGED';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) THEN RAISE EXCEPTION 'SOURCE_V4_ACTIVE_WORK_RETRY_LATER';END IF;
SELECT * INTO STRICT h FROM population_top3000_202608_202609_v1.continuation_handler_v6 WHERE kind='CTX02_PAGE_ADMISSION' FOR UPDATE;
IF h.enabled IS DISTINCT FROM true OR used>=11750000000 OR h.review_event_id<>33427 OR h.function_sha256 IS DISTINCT FROM '7b68f7313f94151d9c8a5590c2b80a5fd74a6c784e5c9a5f4b6c19ceee38252e' OR h.function_sha256 IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(h.function_oid),'UTF8')),'hex') OR encode(sha256(convert_to(h.bounds::text,'UTF8')),'hex') IS DISTINCT FROM 'a1dba514a1fd4550b4bc44433046e8c730ac19861e5e1b2d19615c15f410de21' THEN RAISE EXCEPTION 'SOURCE_V4_POLICY_PREIMAGE_CHANGED';END IF;
newbounds:=jsonb_set(h.bounds,'{global_ceiling,source_bytes}','1500000000'::jsonb);
IF encode(sha256(convert_to(newbounds::text,'UTF8')),'hex') IS DISTINCT FROM '4e1dd5a670260affa577f1d85e72fe6191e14210dc3612dc62343937ab01a31d' OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id='a9140229-5ee4-4ecf-acbc-d5a1a26add29' AND status IN('READY','BLOCKED','COMPLETE') AND input_versions->>'date_plan_id'='ref01-date-fullperiod-v9' AND encode(sha256(convert_to(input_versions::text,'UTF8')),'hex')='1887c0fe3626c09b6c14a317f20a20f1aa7a1aafcc06c987126750f4e24b6283' AND encode(sha256(convert_to(payload::text,'UTF8')),'hex')='ab71fd75eba10d2f9fef3c1dc20fbd5626dc11b4f7daf6f1bcad2f2a52d569c7') THEN RAISE EXCEPTION 'SOURCE_V4_POLICY_OR_SUCCESSOR_BINDING_REJECTED';END IF;
SELECT event_id INTO rid FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='RESOURCE_SOURCE_V4_INDEPENDENT_REVIEW' AND details->>'approved'='true' AND details->>'clearing_id'=q.clearing_id AND details->>'input_sha256'=q.input_sha256 AND details->>'claim_event_id'='36878' AND details->>'probe_result_sha256'=v.result_sha256 AND details->>'old_max_source_bytes'='1000000000' AND details->>'new_max_source_bytes'='1500000000' AND details->>'handler_function_sha256'=h.function_sha256 AND details->>'handler_bounds_sha256'=encode(sha256(convert_to(newbounds::text,'UTF8')),'hex') AND details->>'owner_id'=ctl->>'owner_id' AND details->>'owner_fence'='3' AND details->>'stop_generation'='1' AND details->>'scope_sha256'=ctl->>'scope_sha256' AND nullif(details->>'producer','') IS NOT NULL AND nullif(details->>'reviewer','') IS NOT NULL AND details->>'producer' IS DISTINCT FROM details->>'reviewer' ORDER BY event_id DESC LIMIT 1;
IF rid IS NULL THEN RAISE EXCEPTION 'SOURCE_V4_EXACT_INDEPENDENT_REVIEW_REQUIRED';END IF;
SELECT jsonb_build_object('a',to_jsonb(a)-'max_source_bytes','p',(to_jsonb(p)-'budget_evidence')||jsonb_build_object('budget',p.budget_evidence#-'{resource_limits,max_source_bytes}'),'h',to_jsonb(h)-ARRAY['bounds','review_event_id']) INTO baseline FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
manifest:=population_top3000_202608_202609_v1.population_recovery_manifest_v1();
ALTER TABLE population_top3000_202608_202609_v1.acquisition_control DROP CONSTRAINT acquisition_control_max_source_bytes_check;
ALTER TABLE population_top3000_202608_202609_v1.acquisition_control ADD CONSTRAINT acquisition_control_max_source_bytes_check CHECK(max_source_bytes>=0 AND max_source_bytes<=1500000000);
UPDATE population_top3000_202608_202609_v1.acquisition_control SET max_source_bytes=1500000000 WHERE singleton;
UPDATE population_top3000_202608_202609_v1.pipeline_control SET budget_evidence=jsonb_set(budget_evidence,'{resource_limits,max_source_bytes}','1500000000'::jsonb) WHERE singleton;
UPDATE population_top3000_202608_202609_v1.continuation_handler_v6 SET bounds=newbounds,review_event_id=rid WHERE kind='CTX02_PAGE_ADMISSION';
SELECT jsonb_build_object('a',to_jsonb(a)-'max_source_bytes','p',(to_jsonb(p)-'budget_evidence')||jsonb_build_object('budget',p.budget_evidence#-'{resource_limits,max_source_bytes}'),'h',to_jsonb(ch)-ARRAY['bounds','review_event_id']) INTO poststate FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p CROSS JOIN population_top3000_202608_202609_v1.continuation_handler_v6 ch WHERE a.singleton AND p.singleton AND ch.kind='CTX02_PAGE_ADMISSION';
IF (SELECT max_source_bytes FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton)<>1500000000 OR (SELECT budget_evidence#>>'{resource_limits,max_source_bytes}' FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton) IS DISTINCT FROM '1500000000' OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_handler_v6 WHERE kind=h.kind AND bounds=newbounds AND review_event_id=rid) THEN RAISE EXCEPTION 'SOURCE_V4_CAP_READBACK_FAILED';END IF;
IF baseline IS DISTINCT FROM poststate OR manifest IS DISTINCT FROM population_top3000_202608_202609_v1.population_recovery_manifest_v1() OR (newbounds#-'{global_ceiling,source_bytes}') IS DISTINCT FROM (h.bounds#-'{global_ceiling,source_bytes}') THEN RAISE EXCEPTION 'SOURCE_V4_COLLATERAL_CHANGE';END IF;
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CONTINUATION_MEASURED_ADMISSION_V6',ctl||jsonb_build_object('admission_class','SOURCE_ONLY_FINITE_MEASURED_V4','actor','automation:6adc2c96db348191bca7cf4eacfdac32','clearing_id',q.clearing_id,'input_sha256',q.input_sha256,'claim_event_id',36878,'probe_id',v.probe_id,'probe_result_sha256',v.result_sha256,'available_bytes',available,'mission_relation_bytes',used,'old_max_source_bytes',1000000000,'new_max_source_bytes',1500000000,'handler_bounds_sha256',encode(sha256(convert_to(newbounds::text,'UTF8')),'hex'),'independent_review_event_id',rid,'effects_known',true,'cumulative_counters_preserved',true,'original_deadline_preserved',true,'source_holds_unchanged',true,'no_source_acquisition',true,'code_manifest_unchanged',true,'successor_task_id','a9140229-5ee4-4ecf-acbc-d5a1a26add29','family_accepted',false));
END $source_v4$;
